import{_ as t,o,c as a,a5 as r}from"./chunks/framework.DJo0M80U.js";const h=JSON.parse('{"title":"核心概念","description":"Vue.js 是一个渐进式 JavaScript 框架，主要用于构建用户界面。它的设计思想是尽量简单，易于集成和扩展。以下是 Vue.js 的核心概念： 1. 声明式渲染 Vue.js 使用声明式语法来描述 DOM，这使得代码更加简洁和直观。 \\\\<div id \\"app\\"\\\\ \\\\{。","frontmatter":{"title":"核心概念","date":"2026-08-11T00:00:00.000Z","categories":["Vue 系统教程"],"tags":["Vue","Vue3","前端","教程","OneNote","补充主题"],"description":"Vue.js 是一个渐进式 JavaScript 框架，主要用于构建用户界面。它的设计思想是尽量简单，易于集成和扩展。以下是 Vue.js 的核心概念： 1. 声明式渲染 Vue.js 使用声明式语法来描述 DOM，这使得代码更加简洁和直观。 \\\\<div id \\"app\\"\\\\ \\\\{。","sidebarWeight":19,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/f-vue/核心概念/核心概念.md"},"headers":[],"relativePath":"posts/Vue系统教程/09-补充主题/核心概念.md","filePath":"posts/Vue系统教程/09-补充主题/核心概念.md"}'),s={name:"posts/Vue系统教程/09-补充主题/核心概念.md"};function u(d,e,n,i,c,p){return o(),a("div",null,[...e[0]||(e[0]=[r('<div><h1 id="核心概念" tabindex="-1">核心概念 <a class="header-anchor" href="#核心概念" aria-label="Permalink to &quot;核心概念&quot;">​</a></h1><blockquote><p>本节目标：理解“核心概念”的核心思路，并能把它用于实际开发或面试表达。 Vue.js 是一个渐进式 JavaScript 框架，主要用于构建用户界面。它的设计思想是尽量简单，易于集成和扩展。以下是 Vue.js 的核心概念：</p></blockquote><h3 id="_1-声明式渲染" tabindex="-1">1. <strong>声明式渲染</strong> <a class="header-anchor" href="#_1-声明式渲染" aria-label="Permalink to &quot;1. **声明式渲染**&quot;">​</a></h3><p>Vue.js 使用声明式语法来描述 DOM，这使得代码更加简洁和直观。 &lt;div id=&quot;app&quot;&gt;{{ message }}&lt;/div&gt; &lt;script&gt; var app = new Vue({ el: &#39;#app&#39;, data: { message: &#39;Hello Vue!&#39; } }) &lt;/script&gt; 在上面的例子中，<code>{{ message }}</code> 是一个占位符，会被 Vue 实例中的 <code>message</code> 数据替换。</p><h3 id="_2-组件系统" tabindex="-1">2. <strong>组件系统</strong> <a class="header-anchor" href="#_2-组件系统" aria-label="Permalink to &quot;2. **组件系统**&quot;">​</a></h3><p>组件是 Vue.js 最强大的功能之一。组件允许开发者将 UI 分解成独立、可复用的片段。 Vue.component(&#39;todo-item&#39;, { props: [&#39;todo&#39;], template: &#39;&lt;li&gt;{{ todo.text }}&lt;/li&gt;&#39; }) var app = new Vue({ el: &#39;#app&#39;, data: { groceryList: [ { id: 0, text: &#39;Vegetables&#39; }, { id: 1, text: &#39;Cheese&#39; }, { id: 2, text: &#39;Whatever else humans are supposed to eat&#39; } ] } }) 在上面的例子中，我们定义了一个 <code>todo-item</code> 组件，并在 Vue 实例中使用它。</p><h3 id="_3-响应式数据绑定" tabindex="-1">3. <strong>响应式数据绑定</strong> <a class="header-anchor" href="#_3-响应式数据绑定" aria-label="Permalink to &quot;3. **响应式数据绑定**&quot;">​</a></h3><p>Vue.js 的核心之一是响应式系统。当数据变化时，视图会自动更新。Vue 通过数据劫持和依赖追踪来实现这一点。 var app = new Vue({ el: &#39;#app&#39;, data: { message: &#39;Hello Vue.js!&#39; } }) app.message = &#39;I have changed the data!&#39; // 视图会自动更新</p><h3 id="_4-指令-directives" tabindex="-1">4. <strong>指令（Directives）</strong> <a class="header-anchor" href="#_4-指令-directives" aria-label="Permalink to &quot;4. **指令（Directives）**&quot;">​</a></h3><p>Vue.js 提供了多种指令，用于在模板中操作 DOM。这些指令包括 <code>v-bind</code>、<code>v-model</code>、<code>v-if</code>、<code>v-for</code> 等。 &lt;input v-model=&quot;message&quot;&gt; &lt;p v-if=&quot;seen&quot;&gt;You can see me&lt;/p&gt; 在上面的例子中，<code>v-model</code> 实现了双向数据绑定，而 <code>v-if</code> 则根据 <code>seen</code> 的值来决定是否渲染该元素。</p><h3 id="_5-计算属性和侦听器" tabindex="-1">5. <strong>计算属性和侦听器</strong> <a class="header-anchor" href="#_5-计算属性和侦听器" aria-label="Permalink to &quot;5. **计算属性和侦听器**&quot;">​</a></h3><p>计算属性（computed properties）和侦听器（watchers）是 Vue.js 提供的两种处理数据变化的方式。计算属性基于它们的依赖进行缓存，只有相关依赖发生变化时才重新计算。而侦听器则更适合处理数据变化的异步或复杂逻辑。 var app = new Vue({ el: &#39;#app&#39;, data: { message: &#39;Hello&#39; }, computed: { reversedMessage: function() { return this.message.split(&#39;&#39;).reverse().join(&#39;&#39;) } } })</p><h3 id="_6-生命周期钩子" tabindex="-1">6. <strong>生命周期钩子</strong> <a class="header-anchor" href="#_6-生命周期钩子" aria-label="Permalink to &quot;6. **生命周期钩子**&quot;">​</a></h3><p>Vue 实例在创建时会经过一系列的初始化过程，这个过程中的每个阶段都会触发相应的钩子函数。常用的生命周期钩子包括 <code>created</code>、<code>mounted</code>、<code>updated</code> 和 <code>destroyed</code>。 var app = new Vue({ el: &#39;#app&#39;, data: { message: &#39;Hello Vue.js!&#39; }, created: function() { console.log(&#39;Vue instance is created&#39;) } })</p><h3 id="_7-路由-vue-router" tabindex="-1">7. <strong>路由（Vue Router）</strong> <a class="header-anchor" href="#_7-路由-vue-router" aria-label="Permalink to &quot;7. **路由（Vue Router）**&quot;">​</a></h3><p>Vue Router 是 Vue.js 的官方路由管理器，允许开发者构建单页应用（SPA）。 import Vue from &#39;vue&#39; import VueRouter from &#39;vue-router&#39; Vue.use(VueRouter) const routes = [ { path: &#39;/home&#39;, component: Home }, { path: &#39;/about&#39;, component: About } ] const router = new VueRouter({ routes }) new Vue({ router }).$mount(&#39;#app&#39;)</p><h3 id="_8-状态管理-vuex" tabindex="-1">8. <strong>状态管理（Vuex）</strong> <a class="header-anchor" href="#_8-状态管理-vuex" aria-label="Permalink to &quot;8. **状态管理（Vuex）**&quot;">​</a></h3><p>Vuex 是一个专为 Vue.js 应用程序开发的状态管理模式。它采用集中式存储管理应用的所有组件的状态，并以相应的规则保证状态以一种可预测的方式发生变化。 import Vue from &#39;vue&#39; import Vuex from &#39;vuex&#39; Vue.use(Vuex) const store = new Vuex.Store({ state: { count: 0 }, mutations: { increment (state) { state.count++ } } }) new Vue({ store }).$mount(&#39;#app&#39;) 通过理解和掌握这些核心概念，可以帮助开发者更好地利用 Vue.js 进行高效开发，创建灵活且可维护的应用程序。</p></div>',1)])])}const V=t(s,[["render",u]]);export{h as __pageData,V as default};
